                 "tuViTronDoiNu":  "Phụ nữ tuổi Canh Ngọ nếu sinh vào mùa hạ hoặc mùa xuân là thuận mùa sinh, cuộc sống ổn định, yên ấm, lấy chồng giàu sang và có địa vị. Nếu sinh vào mùa thu hoặc mùa đông thì cuộc đời phải gặp nhiều vất vả, éo le, trắc trở về đường tình duyên. Tuổi này lúc nhỏ thường khó nuôi, nhiều lần phải trải qua tai nạn nguy hiểm đến tính mạng nhưng nhờ ân đức của tổ tiên nên đều có thể tai qua nạn khỏi. Tuổi trẻ thường lận đận vất vả, từ 40 tuổi trở đi mới dần ổn định về sự nghiệp. nên ăn ở hiền lành đức độ, tu nhân tích đức để thanh thản khi về già",
