                 "tuViTronDoiNu":  "Phụ nữ tuổi Kỷ Mùi phần đông có thể gây dựng sự nghiệp lớn, là những người quyền cao chức trọng, phù hợp với những công việc mang tỉnh xã hội. Nếu sinh ban ngày vào mùa xuân hay mùa hè là số phủ quý, sung sướng nhưng nếu sinh vào ban đêm lại là lỗi số, cuộc đời gặp phải nhiều biến động. Người có số mệnh này tính tình trung thực, ngay thẳng, ghét thói xu nịnh, ăn nói có duyên và được nhiều người yêu quý. Tuổi trẻ có thể tạo. dựng nên nghiệp lớn nhưng lại để bị tiêu tán tài sản, gần về già mới ổn định về công danh và sự nghiệp.",
