                 "tuViTronDoiNam":  "Phần đông đàn ông tuổi Ất Mùi có tính tình trung thực, thật thà, có quý nhân phù trợ nên cuộc đời gặp nhiều may mắn, có công việc ổn định và cuộc sống gia đình hạnh phúc. Thường phải xây dựng gia đình và lập nghiệp xa quê mới mong ổn định về đường công danh sự nghiệp. Nếu sinh vào mùa thu hoặc mùa đông là thuận số, trong cuộc đời thường gặp nhiều may mắn. Trường hợp sinh ban đêm mùa xuân hoặc mùa hạ lại là số xấu, cuộc đời phải chịu cảnh lận dặn, vất vả. Về già sống thọ, ổn định, đồng con cháu.",
