                 "tuViTronDoiNu":  "Phụ nữ tuổi Ất Mùi nếu sinh vào mùa thu hoặc mùa đông là thuận sinh, cuộc đời gặp nhiều may mắn, ít biến động, tài vận hanh thông, số có quý nhân phù trợ. Trường hợp sinh vào mùa xuân hoặc mùa hạ là lỗi số, cuộc đời lận đận và thường gặp nhiều khó khăn. Tính tình hiền lành, dễ mến, thích giúp đỡ mọi người và cũng thường nhận được sự giúp đỡ. Phần đông sớm thành đạt, có thể gây dựng sự nghiệp khi còn trẻ nhưng lại dễ bị tiêu tán tài sản, gần 40 tuổi mới dân ổn định. Về già sống thọ, ổn định, đồng con cháu. Nên ăn ở hiến lành, đức độ để có được phúc lộc dài lâu.",
