                 "tuViTronDoiNam":  "Đàn ông tuổi Bính Dần phần đông là người tài giỏi, học rộng ham hiểu biết, số đào hoa nhưng lại gặp nhiều trắc trở về đường tình duyên. Nếu sinh vào mùa xuân hoặc mùa hạ là thuận sinh, cuộc đời được sống trong cảnh ấm no thanh nhàn. Trường hợp sinh vào mùa thu hoặc mùa đông lại là không tốt, cuộc đời gặp nhiều biến động thăng trầm, không ổn định. Đa số đàn ông này đều có cá tính độc lập, tự tay xây dựng sự nghiệp mà ít nhận được sự giúp đỡ hay hỗ trợ người thân. Nên sống hiền lành, tu nhân tích đức để có cuộc sống ổn định khi về già",
