                 "huongBepNu":  "Hợi, Họa hại, Khẩu thiệt, Tây Bắc hoặc Sửu, Tuyệt mệnh, Cô quả, Đông bắc",
                 "cungNam":  "Khôn (Thổ)",
                 "tuViTronDoiNu":  "Phụ nữ tuổi Bính Dần nếu sinh vào mùa thu hoặc mùa đông là thuận mùa sinh, thường có cuộc sống yên ấm, hạnh phúc, lấy chồng giàu sang, có địa vị. Tính tình cương trực, thẳng thắn nên: dễ nảy sinh mâu thuẫn bất hòa với những người trong gia đình, thích giúp đỡ mọi người và cũng thường được mọi người giúp đỡ. Những người số mệnh này thường phải kết hôn và lập nghiệp xa quê mới có thể hạnh phúc, dù lập nên nghiệp lớn nhưng lại dễ bị tiêu tán tài sản (từ năm 31 tuổi trở đi mới tạo dựng được cơ nghiệp nhưng chưa ổn định,khi về già cuộc sống yên ấm, hạnh phúc; nếu có con gái đầu lòng thì thuận)",
