                 "tuViTronDoiNam":  "Đàn ông tuổi Nhâm Tuất thường là những người có cá tính mạnh mẽ, thích giúp đỡ mọi người nhương lại thường phải nhận thiệt thời về mình. Trong cuộc đời nhiều lần phải trải qua tai nạn nguy hiểm đến tính mạng, nhưng nhờ ăn ở hiền lành, tu nhân tích đức nên đều có thể tai qua nạn khỏi. Tuổi trẻ lận đận, vất vả, gắn về già mới được ổn định về công danh sự nghiệp. Về già sống thọ, an cư lạc nghiệp, đông con cháu.",
