                 "tuViTronDoiNu":  "Phụ nữ tuổi Đinh Sửu thường là những người có cuộc đời lận đận, cơ cực và thường gặp phải nhiều khó khăn trong cuộc đời. Nếu sinh vào ban đêm cuộc sống có  phần yên ấm hơn tuy nhiên phải kết hôn muộn mới mong ổn định về đường tình duyên. Phần đông tính tình hiền hậu, vui vẻ, thông minh có ý chí và hiếu kính với cha mẹ. Tuổi trẻ có cơ nghiệp, sớm thành đạt nhưng lại dễ bị tiêu tán tài sản, từ 40 tuổi trở đi mới dần ổn định về sự nghiệp. Người có số mệnh này phải xây dựng gia đình và lập nghiệp xa quê mới mong có thể an cư lạc nghiệp. Nên ăn ở hiền lành, tu nhân tích đức để có được cuộc sống yên ấm thanh thản khi về già",
