                 "soHopNam":  "9",
                 "tuoiKhac":  "Tân Mùi, Kỷ Mùi",
                 "huongVeSinhNam":  "Tân, Ngũ quỷ, Trường bệnh, Chính Tây",
                 "huongVeSinhNu":  "Nhâm, Lục sát, Tự ải, Chính Bắc",
