                 "canChi":  "Quý Sửu",
                 "huongNhaNam":  "Mão, Sinh khí, Tiến điền, Chính Đông (85 - 93) hoặc Giáp, Sinh khí, Vượng tài, Chính Đông (68 - 76)",
                 "tuViTronDoiNam":  "Cuộc đời bôn ba vất và nhiều nhưng không gặt hái được thành công. Sống cuộc đời tha hương, ít nhận được sự giúp đỡ của bạn bè cũng như người thân. Đàn ông tuổi Quý Sửu nếu sinh vào mùa thu là không được mùa sinh, cuộc đời càng gặp nhiều khó khăn, vất vả. Nếu sinh vào mùa đông là được mùa sinh, tuổi trẻ vất vả nhưng sau được hưởng phúc lộc. Tuổi Quý Sửu thuộc cung Tốn, mạng Mộc, vì vậy nhân duyên không tốt, tình duyên gặp nhiều trắc trở tuy nhiên con cháu đông đúc về già có cuộc sống ổn định, đông con cháu.",
                 "amDuong":  "Âm",
                 "tenNenDatNu":  "Lợi, Hoa, Chi, Như, Liên, Phương, Thu, An, Bảo, Tú, Lương, Liên",
