                 "huongNhaNu":  "Mão, Sinh khí, Tiến điền, Chính Đông (85 - 93) hoặc Giáp, Sinh khí, Vượng tài, Chính Đông (68 - 76)",
                 "vatPhamNam":  {
                                    "taiLoc":  "Bể cá hướng Tây Nam, treo tranh Sơn Thủy",
                                    "sucKhoe":  "Đặt bình hoa to trong phòng khách, phòng ngủ, treo tranh ảnh chim hạc theo hướng cát tinh",
                                    "triTue":  "Đặt tượng Phật, Tâm kinh hướng Phúc đức, Phục vị hoặc tháp Văn Xương theo hướng cát tinh",
                                    "congDanh":  "Đặt ấn quan bằng ngọc, treo xây tiền cổ hướng Phúc đức, Phục vị"
                                },
                 "vatPhamNu":  {
                                   "taiLoc":  "Đặt cóc vàng 3 chân, thờ thần tài, treo sâu tiền Ngũ đế theo hướng cát tinh",
                                   "sucKhoe":  "Trồng cây Vạn niên thanh, treo 3 -4 ngọn Trường minh đăng ở cung Sinh khí, Thiên y",
                                   "triTue":  "Đặt tượng, ảnh Bồ Tát, Tâm Kinh, tháp Văn Xương 9 tầng theo hướng cát tinh",
                                   "congDanh":  "Đặt thủy tinh cầu, ấn thăng quan theo hướng cát tinh"
                               },
                 "huongBepNu":  "Sửu, Họa hại, Pháp trường, Đông Bắc",
                 "cungNam":  "Càn (Kim)",
                 "tuViTronDoiNu":  "Phụ nữ tuổi Quý Sửu nếu sinh vào mùa xuân là thuận mùa sinh, thường có cuộc sống thanh nhàn, ổn định tuy nhiên nếu sinh vào mùa thu thường phải sống cuộc đời khó khăn, lận đận, vất vả lo toan cho cuộc sống gia đình. Tính tình ngay thẳng, cương trực, ghét thói xu nịnh, tự thân lập nghiệp mà ít cán sự giúp đỡ hay hỗ trợ từ người khác. Số có quý nhân phù trợ, dù gặp tai nạn nguy hiểm đến tính mạng nhưng nhờ ân đức tổ tiên nên đều tai qua nạn khỏi. Nên ăn ở hiến lành, tu nhân tích đức để có được cuộc sống ổn định, thanh thản khi về già.",
                 "mauHopNu":  "Đỏ, tím, cam",
                 "soHopNam":  "6,7",
                 "tuoiKhac":  "Ất Mùi, Tân Mùi, Đinh Hợi, Đinh Tỵ",
                 "huongVeSinhNam":  "Nhâm, Lục sát, Tự ải, Chính Bắc",
                 "huongVeSinhNu":  "Tân, Ngũ quỷ, Trường bệnh, Chính Tây",
