                 "tuViTronDoiNam":  "Là người kiên cường, quang mình chính đại, thẳng thắn, khẳng khái và có lòng tự tôn lớn, không dễ dàng chấp nhận khuất phục. Cá tính độc lập tự cường, tay trắng làm nên sự nghiệp. Đàn ông tuổi Canh Tý nếu sinh vào mùa đông là được mùa sinh, cả đời được hưởng vinh hoa phú quý, có quyền cao chức trọng. Là đứa con hiếu thảo trong gia đình, khi còn nhỏ hay gặp các vấn đề về sức khỏe, nhưng khi trường thành được hưởng giàu sang phú quỷ, cuộc sống đủ đấy. Nên sống tu nhân tích đức để tạo phúc cho thể hệ con cháu sau này.",
