                 "tuViTronDoiNam":  "Tính tình hiền lành, đôn hậu, có tấm lòng nhân ái tuy nhiên trong lòng lại thường có tâm trạng lo lắng, bất an. Sớm thành đạt, có thể tạo dựng nghiệp lớn nhưng lại dễ bị tiêu tán tài sản. Nếu sinh vào mùa đồng hoặc mùa xuân là được mùa sinh, cuộc đời sống trong cảnh thanh nhàn, sung sướng. Trường hợp sinh vào mùa hạ hoặc mùa thu lại là số xấu, cuộc đời phải trải qua nhiều biến động thăng trầm, số lận dận vất vả. Đàn ông tuổi Tân Dậu thường phải tự tay lập nên sự nghiệp mà ít có sự giúp đỡ hay hỏ trợ từ người thân. Gán về già mới dần ổn định về sự nghiệp, sống trong cảnh giàu sang, đủ đấy. Nên sống hiền lành, đức độ để tạo phúc cho con cháu.",
