                 "tuViTronDoiNam":  "Phần đồng đàn ông tuổi Mậu Thân tính tình hiền lành, vui vẻ, là người có tài nên có thể gây dựng nghiệp lớn. Số tự tay lập nghiệp mà ít nhận được sự giúp đỡ hay hỗ trợ từ người thân. Trường hợp sinh ban đêm vào mùa thu hoặc mùa đông là được mùa sinh, cuộc đời gặp nhiều may mắn, tài vận hanh thông. Lúc nhỏ nhiều lần phải trải qua tai nạn nguy hiểm nhưng nhờ ân đức của tổ tiên nên đều có thể tai qua nạn khỏi. Về chuyện tình duyên cũng gặp nhiều trắc trở, lận đận. Nếu lập gia đình muộn sẽ thuận lợi hơn cho bước đường công danh sự nghiệp cũng như đường đời. Nên sống hiến lành, tu nhân tích đức để tạo phủ cho con cháu sau này.",
