                 "cungNam":  "Khôn (Thổ)",
                 "tuViTronDoiNu":  "Phụ nữ tuổi Mậu Thân nếu sinh ban đêm vào mùa thu hoặc mùa đông là thuận sinh, cuộc đời được sống trong cảnh an nhàn phú quý, gặp nhiều may mắn. Tuy nhiên số này phán dông là vất vả, dù sống trong cảnh giàu sang cũng khó có được hạnh phúc trọn vẹn. Tình tình vui vẻ, dễ mến, ăn nói dễ nghe, thích giúp đỡ mọi người nên thường được mọi người cảm phục và yêu mến. Số này phải lấy chồng và lập nghiệp xa quê mới mong ốn định về sự nghiệp. Nên ăn ở hiến lành, tu nhân tích đức để có được cuộc sống thanh thản khi về già.",
