                 "tuViTronDoiNam":  "Đàn ông tuổi Tân Hợi tỉnh tình thẳng thắn, cương trực, khẳng khái nên thường có mâu thuẫn, bất hòa với mọi người trong gia đình. Số này phần lớn phải kết hôn và lập nghiệp phương xa mới mong có được cuộc sống ổn định. Vì số và mạng tương sinh nên cuộc đời gặp nhiều may mắn, số có quý nhân phù trợ, tài vận hanh thông. Nên ăn ở hiền lành đức độ để có cuộc sống yên ổn, thanh nhàn khi về giả.",
