                 "cungNam":  "Khôn (Thổ)",
                 "tuViTronDoiNu":  "Phần đồng phụ nữ tuổi Tân Hợi dù sống trong cảnh giàu sang hay nghèo khó đều có cuộc sống yên ẩm, an nhàn. Nếu sinh vào ban đêm mùa thu là thuận mùa sinh, cuộc đời gặp nhiều may mắn, tài vận hanh thông, lấy chồng giàu sang và có địa vị, ngược lại nếu sinh vào mùa đông, mùa xuân hoặc mùa hè đều phải chịu cảnh éo le, vất vả, cuộc đời gặp nhiều biến động. Phụ nữ tuổi Tân Hợi thường có tính tình thật thà, để thương, nết na thùy mị nên được nhiều người yêu quý. Sớm thành đạt, khoảng 32 tuổi đã có sự nghiệp ổn định. Về già sống thọ, an cư lạc nghiệp, đông con cháu. Nên sống tu nhân tích đức để có được phúc lộc dài lâu.",
