                 "cungNam":  "Càn (Kim)",
                 "tuViTronDoiNu":  "Phụ nữ tuổi Tân Sửu sinh vào mùa hạ là thuận mùa sinh, cả đời sống trong cảnh giàu sang phú quý, tài vận hanh thông và có địa vị trong xã hội. Tuy nhiên nếu sinh vào ban ngày thì cuộc sống lận đận, khó khăn, phải kết hôn và lập nghiệp xa quê mới có thể an cư lạc nghiệp. Phụ nữ tuổi này thường là những người vui vẻ, sống tình cảm, nội tâm, thích giúp đỡ mọi người và cũng thường được người khác giúp đỡ. Nên sống hiến lành, tu nhân tích đức để tuổi già có được cuộc sống an nhàn, đủ đấy (chủ ý nên tránh ăn thịt chó, mèo, ngựa, trâu),",
