                 "tuViTronDoiNam":  "Thông minh, giỏi giang nhưng tỉnh khí hay thay đổi thất thường. Đàn ông tuổi Tân Sửu nếu sinh ban đêm vào mùa đông là thuận mùa sinh, cuộc đời được hưởng nhiều tài lộc, ngược lại nếu sinh vào ban ngày thì cuộc đời gặp nhiều gian nan vất vả. Khi còn nhỏ gặp nhiều vấn đề về sức khỏe, nhưng do phúc lộc tổ tiên để lại nên có thể tai qua nạn khỏi. Tính cách thân thiện nên thường được mọi người yêu mến, cuộc đời phải bôn ba nhiều mới có thể thành công. Tình duyên trác trở, thường phải lập gia thất hai lần thì tình duyên mới bền chặt.",
