                 "tuViTronDoiNam":  "Đàn ông tuổi Giáp Thân dù sống trong cảnh giàu sang hay nghèo khó đều có cuộc sống tương đổi ổn định, an nhàn. Tuổi nhỏ ốm yếu, khó nuôi, nhiều lán phải trải qua tai nạn nguy hiểm đến tính mạng nhưng nhờ ăn dức của tổ tiên nên có thể tai qua nạn khỏi. Sớm thành đạt, có thể gây dựng nghiệp lớn nhưương lại dễ bị tiêu tân tài sản. Về chuyện tình duyên cũng gặp nhiều trắc trở, lận đận, có thể phải qua 2 lần đò mới mong có được hạnh phúc trọn vẹn. Tính tình thẳng thắn, cương trực nên thường có bắt hỏa, mâu thuẩn với mọi người trong gia đình. Về già sống thọ, ổn định, sống trong cảnh giàu sang, đủ đầy",
