                 "huongNhaNam":  "Dần, Sinh khí, Quan quý, Đông Bắc (53 - 66)",
                 "tuViTronDoiNam":  "Đàn ông tuổi Quý Mão phần lớn là những người học rộng, ham hiểu biết, có ý chí, sớm thành đạt và có thể gây dựng nghiệp lớn. Nếu sinh vào mùa thu là được mùa sinh, cuộc đời được sống trong cảnh sung sướng, thanh nhàn. Trường hợp sinh vào mùa hạ lại là số xấu, cuộc đời phải trải qua nhiều biến động thăng trầm, số lận đận vất vả. Tỉnh tình trung thực, thẳng thắn, thích giúp đỡ mọi người nên được nhiều người yêu quý, ngưỡng mộ. Nên sống đức độ, hiến lành, tu nhân tích đức để tạo phúc cho thể hệ con cháu.",
