                 "tuViTronDoiNam":  "Phần đông đàn ông có can Nhâm cuộc đời gặp nhiều may mắn, tài vận hanh thông và có một cuộc sống gia đình ổn định, hạnh phúc. Đặc biệt những người sinh vào ban ngày cả đời được hưởng vinh hoa phú quý, có quyền cao chức trọng. Tính tình hiền lành, cương trực, ngay thẳng, thích giúp đỡ mọi người và cũng thường được nhiều người giúp đỡ. Tình duyên có phân trắc trở, lận đận, có thể phải qua hai lần đò mới mong tìm được hạnh phúc thực sự. Tuổi trẻ lận đận vất vả, gắn về già mới có được cuộc sống ổn định. Nên ăn ở hiền lành, đức độ để có được cuộc sống thanh nhàn khi về già.",
