                 "tuViTronDoiNam":  "Đàn ông tuổi Mậu Dần là những người có cá tính, thẳng thắn, thường tự tay lâập nên sự nghiệp mà ít có sự hỗ trợ hay giúp đỡ của người thân. Nếu sinh vào ban đêm là thuận sinh, cuộc đời gặp nhiều may mắn, tài vận hanh thông và có cuộc sống gia đình hạnh phúc. Trường hợp sinh vào mùa xuân là số xấu, tuổi trẻ gặp nhiều gian truân vất vả, số lận đận, sau tuổi 40 mới dần ổn định. Về già sống thọ, đông con cháu. Nên làm nhiều  việc thiện để tạo phúc cho con cháu về sau",
