                 "tuViTronDoiNu":  "Phần đông phụ nữ tuổi Mậu Dần cuộc đời vất vả. Nếu sinh vào mùa hạ là thuận mùa sinh, cuộc sống an nhàn, hạnh phúc, lấy chồng giàu sang, có địa vị. Trường hợp những người sinh vào các mùa khác phần đông phải chịu cuộc sống éo le, gian truân, trắc trở về đường tình duyên. Hầu hết những người có số mệnh này tự tay lập nên sự nghiệp và ít có sự hỗ trợ hay giúp đỡ từ mọi người, có thể tạo nên sự nghiệp lớn nhưng lại dễ bị tiêu tán tài sản. Có cá tính, thẳng thắn nên dễ bị mâu thuẫn, bất hòa với mọi người trong gia đình. Về già thường có cuộc sống đầy đủ, yên ấm, đông con cháu (chú ý nên kiêng ăn thịt chó, mèo, rùa, ngựa, trâu, ...)",
