                 "tuViTronDoiNam":  "Đàn ông tuổi Canh thìn thường có tính tình ngay thẳng, trung thực, số phải xây dựng gia đình và lập nghiệp phương xa mới mong ổn định và có thể tìm được hạnh phúc thực sự. Nếu sinh vào ban đêm là được mùa  sinh, cuộc đời được sống trong cảnh giàu sang phú quý, đủ đầy. Trường hợp sinh vào mùa xuân là số xấu, cả đời phải sống trong cảnh lận đận, vất vả. về chuyện tình duyên có thể gặp nhiều trắc trở, lận đận, khó yên bề gia thất. Về già sống thọ ổn định, đông con cháu",
