                 "tuViTronDoiNam":  "Phần lớn đàn ông tuổi Đinh Dậu là những người học rộng, ham hiểu biết, sớm thành đạt, có thể tự tay gây dựng nghiệp lớn. Tính tình thẳng thắn, mạnh mẽ, coi trọng đạo lý, thích giúp đỡ mọi người và cũng thường được nhiều người giúp đỡ. Nếu sinh vào mùa xuân hoặc mùa hạ là được mùa sinh, cuộc đời sống trong cảnh thanh nhàn, sung sướng. Tuy nhiên thường phải xây dựng gia đình và lập nghiệp phương xa mới mong ổn định về đường công danh sự nghiệp cũng như đường đời. Về già sống thọ, ổn định, đồng con cháu.",
