                 "tuViTronDoiNu":  "Phụ nữ tuổi Bính Thìn nếu sinh vào mùa hè là thuận mùa sinh, dù sống trong cảnh giàu sang hay nghèo khó cũng đều có cuộc sống yên ấm, hạnh phúc (nếu sinh vào ban ngày thì càng thuận). Ngược lại nếu sinh vào mùa xuân là lỗi mùa sinh, cuộc đời gặp nhiều khó cực, éo le, tình duyên trắc trở. Phần đông phụ nữ tuổi Binh Thin tính tình hiền hậu, thông minh, chung thủy và dễ tha thứ trong tình yêu. Tuổi trẻ thường vất vả, công việc không ổn định, sau 40 tuổi mới lập nên sự nghiệp, tài vận hanh thông, có quý nhân phù trợ. Về già có cuộc sống ổn định, an cư lạc nghiệp, đông con cháu, sống thọ.",
