                 "tuViTronDoiNam":  "Đường đời nói chung nhiều gập ghềnh trắc trỏe, phải bôn ba nhiều, sống cuộc đời tha hương. Cá tính độc lập tự cường, ít nhận được sự hỗ trợ, giúp đỡ của bạn bè cũng như người thân. Trong cuộc sống gặp nhiều điều phiến não, tâm tư tình cảm, phức tạp. Nhân duyên không tốt, gia đình thường bất hòa.. Tuy nhiên trường hợp những người sinh vào mùa thu hoặc mùa đông là được mùa sinh, cả đời được hưởng vinh hoa phú quý",
